"""Reusable column definitions shared by the models."""

from __future__ import annotations

import uuid
from datetime import datetime

from sqlalchemy import DateTime, Uuid, func
from sqlalchemy.orm import Mapped, mapped_column


class UuidPrimaryKeyMixin:
    """Primary key generated by the database.

    Generating identifiers in PostgreSQL rather than in Python keeps them
    monotonic-free and collision-free without coordination, and it means a row
    inserted by any tool — migration, script or service — gets a valid id.
    """

    id: Mapped[uuid.UUID] = mapped_column(
        Uuid(as_uuid=True),
        primary_key=True,
        server_default=func.gen_random_uuid(),
    )


class CreatedAtMixin:
    """Creation timestamp recorded by the database, not by the application.

    A clock on the application server can be wrong or skewed between instances;
    the database clock is the single reference for ordering.
    """

    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True),
        nullable=False,
        server_default=func.now(),
    )
